<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import AdminConfirmDialog from '@/Components/Admin/AdminConfirmDialog.vue';
import AdminDataCard from '@/Components/Admin/AdminDataCard.vue';
import AdminErrorSummary from '@/Components/Admin/AdminErrorSummary.vue';
import AdminFormField from '@/Components/Admin/AdminFormField.vue';
import AdminMediaPicker from '@/Components/Admin/AdminMediaPicker.vue';
import AdminPageHeader from '@/Components/Admin/AdminPageHeader.vue';
import AdminSelect from '@/Components/Admin/AdminSelect.vue';
import AdminTextInput from '@/Components/Admin/AdminTextInput.vue';
import AdminTextarea from '@/Components/Admin/AdminTextarea.vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import draggable from 'vuedraggable';
import { ref, watch } from 'vue';

const props = defineProps({ page: { type: Object, required: true } });
const module = props.page.module; const product = module.product;
const form = useForm({ name: product?.name || '', slug: product?.slug || '', sku: product?.sku || '', description: product?.description || '', price: product?.price ?? 0, stock: product?.stock ?? 0, status: product?.status || 'active', specifications: product?.specifications?.length ? product.specifications : [{ key: '', value: '' }], version: product?.version || null });
const showPicker = ref(false); const pickerIs360 = ref(false); const deletingImage = ref(null); const uploading = ref(false); const normalImages = ref([]); const images360 = ref([]);
const syncImages = (images = []) => { normalImages.value = images.filter((image) => !image.is_360); images360.value = images.filter((image) => image.is_360); };
syncImages(product?.images || []);
watch(() => props.page.module.product?.images, (images) => syncImages(images || []), { deep: true });
const addSpec = () => form.specifications.push({ key: '', value: '' }); const removeSpec = (index) => form.specifications.splice(index, 1);
const syncFromPage = (page) => { const updated = page.props.page?.module?.product; if (updated) { syncImages(updated.images || []); if (updated.version) form.version = updated.version; } };
const save = () => product ? form.put(route('admin.products.update', product.id), { onSuccess: (page) => { syncFromPage(page); form.defaults(form.data()); form.reset(); } }) : form.post(route('admin.products.store'));
const uploadImages = (event, is360) => { if (!product || !event.target.files.length) return; const data = new FormData(); Array.from(event.target.files).forEach((file) => data.append('images[]', file)); if (is360) data.append('is_360', '1'); uploading.value = true; router.post(route('admin.products.images.upload', product.id), data, { forceFormData: true, preserveScroll: true, onSuccess: syncFromPage, onFinish: () => { uploading.value = false; event.target.value = ''; } }); };
const selectMedia = (media) => { showPicker.value = false; if (product) router.post(route('admin.products.images.from-media', product.id), { media_id: media.id, is_360: pickerIs360.value ? 1 : 0 }, { preserveScroll: true, onSuccess: syncFromPage }); };
const deleteImage = () => { router.delete(route('admin.products.images.delete', [product.id, deletingImage.value.id]), { preserveScroll: true, onSuccess: syncFromPage, onFinish: () => { deletingImage.value = null; } }); };
const saveOrder = () => { const order = [...normalImages.value, ...images360.value].map((image) => image.id); router.post(route('admin.products.images.reorder', product.id), { order }, { preserveScroll: true, onSuccess: syncFromPage }); };
const moveImage = (group, index, amount) => { const list = group === '360' ? images360.value : normalImages.value; const next = index + amount; if (next < 0 || next >= list.length) return; [list[index], list[next]] = [list[next], list[index]]; saveOrder(); };
</script>

<template>
    <Head :title="page.meta.title" /><AuthenticatedLayout><AdminPageHeader :title="page.meta.title"><Link :href="route('admin.products.index')" class="text-sm text-admin-content-muted">Quay lại</Link></AdminPageHeader><div class="mt-6 space-y-6"><AdminErrorSummary :errors="form.errors" /><AdminDataCard title="Thông tin sản phẩm"><form class="space-y-5" @submit.prevent="save"><div class="grid gap-4 md:grid-cols-2"><AdminFormField label="Tên" for-id="product-name" :error="form.errors.name"><AdminTextInput id="product-name" v-model="form.name" /></AdminFormField><AdminFormField label="Đường dẫn" for-id="product-slug" :error="form.errors.slug"><AdminTextInput id="product-slug" v-model="form.slug" /></AdminFormField><AdminFormField label="SKU" for-id="product-sku" :error="form.errors.sku"><AdminTextInput id="product-sku" v-model="form.sku" /></AdminFormField><AdminFormField label="Giá" for-id="product-price" :error="form.errors.price"><AdminTextInput id="product-price" v-model.number="form.price" type="number" /></AdminFormField><AdminFormField label="Tồn kho" for-id="product-stock" :error="form.errors.stock"><AdminTextInput id="product-stock" v-model.number="form.stock" type="number" /></AdminFormField><AdminFormField label="Trạng thái" for-id="product-status" :error="form.errors.status"><AdminSelect id="product-status" v-model="form.status" :options="module.statuses" /></AdminFormField></div><AdminFormField label="Mô tả" for-id="product-description" :error="form.errors.description"><AdminTextarea id="product-description" v-model="form.description" rows="8" /></AdminFormField><AdminFormField label="Thông số" :error="form.errors.specifications"><div class="space-y-2"><div v-for="(spec, index) in form.specifications" :key="index" class="flex gap-2"><AdminTextInput v-model="spec.key" placeholder="Tên thông số" /><AdminTextInput v-model="spec.value" placeholder="Giá trị" /><button type="button" class="px-2 text-admin-danger" :aria-label="`Xóa thông số ${index + 1}`" @click="removeSpec(index)">×</button></div><button type="button" class="text-sm text-admin-accent" @click="addSpec">Thêm thông số</button></div></AdminFormField><div class="flex justify-end"><button type="submit" :disabled="form.processing" class="rounded bg-admin-accent px-5 py-2 text-sm font-semibold text-admin-page">{{ form.processing ? 'Đang lưu...' : 'Lưu sản phẩm' }}</button></div></form></AdminDataCard>
        <AdminDataCard v-if="product" title="Ảnh sản phẩm"><div class="flex flex-wrap gap-3"><label class="cursor-pointer rounded border border-admin-border px-4 py-2 text-sm text-admin-content"><input type="file" class="sr-only" multiple accept="image/jpeg,image/png,image/webp,image/gif" :disabled="uploading" @change="uploadImages($event, false)" />Tải ảnh thường</label><label class="cursor-pointer rounded border border-admin-border px-4 py-2 text-sm text-admin-content"><input type="file" class="sr-only" multiple accept="image/jpeg,image/png,image/webp,image/gif" :disabled="uploading" @change="uploadImages($event, true)" />Tải ảnh 360</label><button type="button" class="rounded border border-admin-border px-4 py-2 text-sm text-admin-content" @click="pickerIs360 = false; showPicker = true">Gắn ảnh thường</button><button type="button" class="rounded border border-admin-border px-4 py-2 text-sm text-admin-content" @click="pickerIs360 = true; showPicker = true">Gắn ảnh 360</button></div><section class="mt-5"><h3 class="text-sm font-semibold text-admin-content">Ảnh thường</h3><draggable v-model="normalImages" item-key="id" class="mt-3 grid grid-cols-2 gap-3 sm:grid-cols-5" handle=".image-handle" @end="saveOrder"><template #item="{ element: image, index }"><div class="relative border border-admin-border p-2"><button type="button" class="image-handle absolute left-1 top-1 cursor-grab text-xs text-admin-content-muted" aria-label="Kéo ảnh">::</button><img :src="image.url" :alt="image.file_name" class="aspect-square w-full object-cover" /><div class="mt-2 flex items-center justify-between"><div class="flex gap-2"><button type="button" title="Đưa ảnh sang trái" :disabled="index === 0" aria-label="Đưa ảnh sang trái" @click="moveImage('normal', index, -1)">←</button><button type="button" title="Đưa ảnh sang phải" :disabled="index === normalImages.length - 1" aria-label="Đưa ảnh sang phải" @click="moveImage('normal', index, 1)">→</button></div><button type="button" class="bg-admin-danger px-2 py-1 text-xs text-white" @click="deletingImage = image">Xóa</button></div></div></template></draggable></section><section class="mt-6"><h3 class="text-sm font-semibold text-admin-content">Ảnh 360</h3><draggable v-model="images360" item-key="id" class="mt-3 grid grid-cols-2 gap-3 sm:grid-cols-5" handle=".image-handle" @end="saveOrder"><template #item="{ element: image, index }"><div class="relative border border-admin-border p-2"><button type="button" class="image-handle absolute left-1 top-1 cursor-grab text-xs text-admin-content-muted" aria-label="Kéo ảnh">::</button><img :src="image.url" :alt="image.file_name" class="aspect-square w-full object-cover" /><div class="mt-2 flex items-center justify-between"><div class="flex gap-2"><button type="button" title="Đưa ảnh sang trái" :disabled="index === 0" aria-label="Đưa ảnh sang trái" @click="moveImage('360', index, -1)">←</button><button type="button" title="Đưa ảnh sang phải" :disabled="index === images360.length - 1" aria-label="Đưa ảnh sang phải" @click="moveImage('360', index, 1)">→</button></div><button type="button" class="bg-admin-danger px-2 py-1 text-xs text-white" @click="deletingImage = image">Xóa</button></div></div></template></draggable></section></AdminDataCard></div><AdminMediaPicker :open="showPicker" media-type="image" @close="showPicker = false" @select="selectMedia" /><AdminConfirmDialog :open="!!deletingImage" title="Xóa ảnh sản phẩm" message="Chỉ bản sao của sản phẩm bị xóa; tệp gốc vẫn được giữ." confirm-label="Xóa ảnh" danger @cancel="deletingImage = null" @confirm="deleteImage" /></AuthenticatedLayout>
</template>
